INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u05-l01','course-a1-foundations','fruit-and-vegetables','Fruit and Vegetables','Name common fruit and vegetables and talk about simple food choices.','A1',21,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u05-l01-q01','a1-u05-l01','multiple_choice','Which one is a fruit?','[{"id":"a","text":"apple"},{"id":"b","text":"carrot"},{"id":"c","text":"potato"}]','a','An apple is a fruit.',1),
('a1-u05-l01-q02','a1-u05-l01','multiple_choice','Choose the plural of tomato.','[{"id":"a","text":"tomatos"},{"id":"b","text":"tomatoes"},{"id":"c","text":"tomatoies"}]','b','The plural of tomato is tomatoes.',2),
('a1-u05-l01-q03','a1-u05-l01','multiple_choice','Complete: I eat ___ banana.','[{"id":"a","text":"a"},{"id":"b","text":"an"},{"id":"c","text":"some"}]','a','Use a before a consonant sound.',3),
('a1-u05-l01-q04','a1-u05-l01','multiple_choice','Which word is a vegetable?','[{"id":"a","text":"grape"},{"id":"b","text":"onion"},{"id":"c","text":"pear"}]','b','An onion is a vegetable.',4);
