INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u05-l03','course-a1-foundations','at-the-cafe','At the Café','Understand a simple café menu and order food and drinks politely.','A1',23,1,'published');
