('a1-u05-l03-q01','a1-u05-l03','multiple_choice','Choose a polite order.','[{"id":"a","text":"A coffee, please."},{"id":"b","text":"Give coffee now."},{"id":"c","text":"Coffee you."}]','a','A short request with please is polite.',1),
('a1-u05-l03-q02','a1-u05-l03','multiple_choice','What does a menu show?','[{"id":"a","text":"food and drink choices"},{"id":"b","text":"bus times"},{"id":"c","text":"classroom rules"}]','a','A menu lists food and drink choices.',2),
('a1-u05-l03-q03','a1-u05-l03','multiple_choice','Complete: I''d like ___ sandwich, please.','[{"id":"a","text":"a"},{"id":"b","text":"an"},{"id":"c","text":"any"}]','a','Use a before sandwich.',3),
('a1-u05-l03-q04','a1-u05-l03','multiple_choice','What can you say after receiving your order?','[{"id":"a","text":"Thank you."},{"id":"b","text":"Good night."},{"id":"c","text":"I am twelve."}]','a','Thank you is a polite response.',4);
