INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u05-l04','course-a1-foundations','likes-and-dislikes','Likes and Dislikes','Say which foods and drinks you like or do not like.','A1',24,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u05-l04-q01','a1-u05-l04','multiple_choice','Complete: I ___ apples.','[{"id":"a","text":"like"},{"id":"b","text":"likes"},{"id":"c","text":"liking"}]','a','Use the base verb with I.',1),
('a1-u05-l04-q02','a1-u05-l04','multiple_choice','Choose the correct negative sentence.','[{"id":"a","text":"I don''t like coffee."},{"id":"b","text":"I doesn''t like coffee."},{"id":"c","text":"I not like coffee."}]','a','Use don''t with I.',2),
('a1-u05-l04-q03','a1-u05-l04','multiple_choice','Choose the correct question.','[{"id":"a","text":"Do you like tea?"},{"id":"b","text":"Does you like tea?"},{"id":"c","text":"Are you like tea?"}]','a','Use Do with you.',3),
('a1-u05-l04-q04','a1-u05-l04','multiple_choice','Choose a suitable answer: Do you like rice?','[{"id":"a","text":"Yes, I do."},{"id":"b","text":"Yes, I am."},{"id":"c","text":"Yes, I likes."}]','a','Use do in a short answer to a Do-question.',4);
